# Tsek.ph entries are fact-check articles, not the raw claim being checked.
# This function tries to extract just the claim text from the article.
# It tries four approaches in order: keyword patterns, quoted text,
# first sentences, and finally a character limit fallback.


import re

_CLAIM_INTRODUCERS = [
    r"(?:the claim|ang paghahabol|ang claim)[\s:]+(.+?)(?:\. |\n\n|$)",
    r"(?:claim[:\s]+)(.+?)(?:\. |\n\n|$)",
    r"(?:pahayag|iniulat)[\s:]+(.+?)(?:\. |\n\n|$)",
    r"(?:according to[\s:]+)(.+?)(?:\. |\n\n|$)",
]

def extract_claim_from_factcheck(article_text, max_len=500):
    """Extract the claim being fact-checked from a Tsek.ph article."""

    if not article_text:
        return ""
    text = str(article_text).strip()

    # try to find the claim using keyword patterns like "the claim:" or "ayon sa:"
    for pat in _CLAIM_INTRODUCERS:
        m = re.search(pat, text, flags=re.IGNORECASE | re.DOTALL)
        if m:
            ext = m.group(1).strip()
            if 5 <= len(ext.split()) <= 80:  # skip if too short or too long
                return ext[:max_len]

    # try to find quoted text which often contains the claim
    quotes = re.findall(r'["\u201c\u201d\u2018\u2019\'](.+?)["\u201c\u201d\u2018\u2019\']',
                        text)
    if quotes:
        longest = max(quotes, key=lambda q: len(q.split()))
        if 5 <= len(longest.split()) <= 100:
            return longest.strip()[:max_len]

    # fall back to the first two sentences
    sents = re.split(r"(?<=[.!?])\s+", text)
    if sents:
        first = " ".join(sents[:2])
        if len(first.split()) >= 5:
            return first[:max_len]

    # last resort: just return the first 500 characters
    return text[:max_len]



# Computes three text features: Emotional Tone (ET), Grammar Quality (GQ),
# and Citation Strength (CS).
# ET combines VADER sentiment for English and the Filipino lexicon for Tagalog.
# For mixed language text both scores are blended based on token coverage.
# GQ uses LanguageTool for English. For Tagalog or Taglish text it switches
# to heuristic signals to avoid false grammar errors on Filipino words.
# CS checks for citations, trusted domains, organization names, and factual words.


