def _filipino_token_ratio(tokens):
    """Fraction of tokens that are Filipino (lexicon + function words)."""
    if not tokens:
        return 0.0
    fil = sum(1 for t in tokens
              if t in _FILIPINO_VOCAB or t in _TAGALOG_MARKERS)
    return fil / len(tokens)

def _vader_coverage(tokens):
    """
    Fraction of tokens that VADER 'knows' (has a non-zero lexicon entry).
    Uses VADER's internal SentimentIntensityAnalyzer lexicon dict.
    """
    if not VADER_OK or not tokens:
        return 0.0
    lex = _vader.lexicon          # dict: word → valence float
    known = sum(1 for t in tokens if t.lower() in lex)
    return known / len(tokens)


# =============================================================================
# 1.  EMOTIONAL TONE  (ET)   0 = calm/neutral  →  1 = provocative/emotional
#
# HYBRID COMPUTATION:
#
#   Step 1 — VADER base (English sentiment):
#     Run VADER on the full text. VADER's compound score is in [-1, +1].
#     Convert to 0-1 "emotionality" with negative-biased scaling:
#       compound ≤ -0.05  →  base_vader = min(1, |compound| × 1.2)
#       compound ≥  0.60  →  base_vader = (compound-0.60)/0.40 × 0.40
#       otherwise         →  base_vader = |compound| × 0.15  (dampen neutral)
#
#   Step 2 — Filipino lexicon base (Tagalog sentiment):
#     Count pos/neg hits from Cell 4 lexicons.
#     Weight negative hits 1.3× (negative emotion is a stronger fake signal).
#     base_lex = (neg×1.3 + pos×0.85) / (total + 2.0)
#
#   Step 3 — Coverage-weighted blend:
#     vader_cov = fraction of tokens VADER's lexicon recognises
#     fil_ratio = fraction of tokens that are Filipino words
#     Both scores are averaged, weighted by their respective coverage:
#       total_cov = vader_cov + fil_ratio + ε   (avoid division by zero)
#       base = (vader_cov × base_vader + fil_ratio × base_lex) / total_cov
#
#   Step 4 — Language-agnostic heuristics (always run, capped at 0.35):
#     excl_density  = min(1, !-count / n_words × 5)
#     caps_ratio    = min(1, ALL-CAPS-word-count / n_words × 8)
#     intens_ratio  = min(1, intensifier-hits / n_words × 10)
#     heur = min(0.35, 0.35×excl + 0.30×caps + 0.20×intens + 0.15×elong)
#
#   Step 5 — Final:
#     ET = min(1, 0.65 × base + heur)
# =============================================================================
def get_emotional_tone(text, lang_hint=None):
    txt     = (text or "").strip()
    if not txt:
        return 0.0

    tokens  = re.findall(r"\w+", txt.lower())
    words   = txt.split()
    n_words = max(1, len(words))

    # Step 1: compute VADER sentiment score────────
    if VADER_OK:
        comp = _vader.polarity_scores(txt).get("compound", 0.0)
        if comp <= -0.05:
            base_vader = min(1.0, abs(comp) * 1.2)
        elif comp >= 0.60:
            base_vader = (comp - 0.60) / 0.40 * 0.40
        else:
            base_vader = abs(comp) * 0.15
        vader_cov = _vader_coverage(tokens)
    else:
        base_vader = 0.0
        vader_cov  = 0.0

    # Step 2: compute Filipino lexicon sentiment score────────
    pos   = sum(1 for w in tokens if w in filipino_positive)
    neg   = sum(1 for w in tokens if w in filipino_negative)
    total = pos + neg
    if total > 0:
        base_lex = min(1.0, (neg * 1.3 + pos * 0.85) / (total + 2.0))
    else:
        base_lex = 0.0
    fil_ratio = _filipino_token_ratio(tokens)

    # Step 3: blend both scores weighted by how many tokens each covers────────
    total_cov = vader_cov + fil_ratio + 1e-9
    base = (vader_cov * base_vader + fil_ratio * base_lex) / total_cov

    # Step 4: add heuristic signals that work for any language────────
    excl_density = min(1.0, txt.count("!") / n_words * 5)
    alpha_words  = [re.sub(r"[^a-zA-Z]", "", w) for w in words]
    caps_words   = [w for w in alpha_words if w.isupper() and len(w) > 3]
    caps_ratio   = min(1.0, len(caps_words) / n_words * 8)
    elong_count  = sum(1 for w in words if re.search(r"(.)\1{2,}", w.lower()))
    elong_ratio  = min(1.0, elong_count / n_words * 10)

    intens_en = {"very", "extremely", "absolutely", "totally",
                 "unbelievably", "shocking", "horrifying"}
    intens_tl = {"sobrang", "talaga", "napaka", "grabe", "sobra-sobra",
                 "lubos", "talagang", "ubod", "halos", "masyadong",
                 "labis", "matinding"}
    intens_all = intens_en | intens_tl
    intens_ratio = min(1.0, sum(1 for w in tokens if w in intens_all) / n_words * 10)

    heur = min(0.35,
               0.35 * excl_density +
               0.30 * caps_ratio   +
               0.20 * intens_ratio +
               0.15 * elong_ratio)

    # Step 5: combine base and heuristics into final ET score────────
    ET = float(min(1.0, 0.65 * base + heur))
    return ET


# Grammar Quality (GQ): 0 means clean writing, 1 means poor writing quality.
# For English text LanguageTool is used to count actual grammar errors.
# If the text is Tagalog or Taglish the system skips LanguageTool to avoid
# flagging Filipino words as errors, and uses heuristic signals instead.

# ng/nang confusion detector (Filipino-specific).
# "Nang" is required before adjectives/adverbs; "ng" is the genitive marker.
# Pattern: "ng" followed by a common Filipino adverb/adjective where "nang"
# should be used. List sourced from KWF (Komisyon sa Wikang Filipino) guidelines.
_NANG_ADVERBS = {
    "mabilis", "mabagal", "maayos", "maigi", "malinaw", "maliwanag",
    "maganda", "masama", "mahal", "mura", "malakas", "mahina",
    "mataas", "mababa", "malayo", "malapit", "matagal", "maikli",
    "marami", "kaunti", "lubos", "ganap", "tuluyan", "dahan-dahan",
    "paunti-unti", "pabilis", "pabagal", "unti-unti", "todo",
    "husto", "tama", "mali", "maaga", "huli", "lagi", "palagi",
    "minsan", "madalas", "bihira", "paminsan-minsan",
}
_NG_NANG_PAT = re.compile(
    r'ng\s+(' + '|'.join(re.escape(w) for w in _NANG_ADVERBS) + r')',
    flags=re.IGNORECASE
)

# detect vague attribution words without a named source
_VAGUE_ATTR = re.compile(
    r'(?:daw|raw|aniya|ayon|malamang|allegedly|reportedly|sources say|'
    r'some say|people say|may claim|it is said|word has it|'
    r'rumored|rumoured|unconfirmed|reportedly)',
    flags=re.IGNORECASE
)

# pattern for repeated punctuation
_REPEAT_PUNCT = re.compile(r'[!?]{2,}|\.{3,}')

# simple sentence splitter
_SENT_SPLIT = re.compile(r'(?<=[.!?])\s+')


def get_grammar_quality(text, lang_hint=None):
    """
    GQ v5 — Writing Professionalism Proxy
    ======================================
    Measures quantifiable writing-quality deficiencies that correlate with
    low-credibility sources across English, Filipino, and Taglish.

    Note: this is NOT a grammar checker for Filipino/Taglish (no such
    rule-based tool exists). It is a writing professionalism proxy.
    All signals below are language-agnostic unless noted.

    Signals
    -------
    LanguageTool (EN only, when available):
        Real grammar error rate via LanguageTool's rule engine.

    Universal heuristic signals (all three languages):
        S1  repeated_punct   — !! ?? ... density (tabloid signal)
        S2  caps_ratio       — ALL-CAPS word ratio (shouting)
        S3  sentence_starts  — fraction of sentences NOT starting with capital
                               (lower = worse for EN; neutral for mixed text)
        S4  spacing_errors   — missing space after punctuation (excl. URLs)
        S5  repeat_words     — consecutive repeated words
        S6  sent_len_cv      — coefficient of variation in sentence lengths
                               (very short choppy OR very long run-on sentences
                               both indicate low writing quality)

    Filipino-specific signals (Tagalog / Taglish):
        S7  ng_nang_errors   — "ng" used where "nang" is required before
                               adverbs/adjectives (KWF documented error)
        S8  vague_attr       — density of unverified attribution markers
                               (daw, raw, allegedly, sources say, etc.)
    """
    txt     = (text or "").strip()
    if not txt:
        return 0.5

    tokens  = re.findall(r"\w+", txt.lower())
    words   = txt.split()
    n_words = max(1, len(words))
    txt_no_url = re.sub(r"https?://\S+|www\.\S+", " ", txt)

    fil_ratio = _filipino_token_ratio(tokens)
    use_lt    = LT_OK and _LT_TOOL is not None and fil_ratio <= 0.20

    # use LanguageTool for English text────
    if use_lt:
        try:
            matches = _LT_TOOL.check(txt[:1000])
            grammar_matches = [
                m for m in matches
                if getattr(m, "ruleIssueType", "") not in
                   ("style", "register", "locale-violation")
            ]
            lt_score = float(min(1.0, len(grammar_matches) / n_words * 5))
        except Exception:
            lt_score = None
    else:
        lt_score = None

    # signal 1: repeated punctuation like !! or ???────────
    # common in tabloid or emotional writing
    rp_hits    = len(_REPEAT_PUNCT.findall(txt))
    s1_repeat_punct = min(1.0, rp_hits / n_words * 15)

    # signal 2: proportion of words in all caps────────
    alpha_words = [re.sub(r"[^a-zA-Z]", "", w) for w in words]
    caps_words  = [w for w in alpha_words if w.isupper() and len(w) > 3]
    s2_caps = min(1.0, len(caps_words) / n_words * 15)

    # signal 3: how many sentences start without a capital letter────────
    # only used for English text
    if fil_ratio <= 0.30:
        sents = _SENT_SPLIT.split(txt_no_url)
        sents = [s.strip() for s in sents if len(s.strip()) > 3]
        if sents:
            uncapped = sum(1 for s in sents
                           if s[0].islower() and s[0].isalpha())
            s3_caps_start = uncapped / len(sents)
        else:
            s3_caps_start = 0.0
    else:
        s3_caps_start = 0.0   # skip for Filipino-dominant text

    # signal 4: missing space after punctuation marks────────
    missing_sp = len(re.findall(r"[.!?,;][A-Za-z]", txt_no_url))
    s4_spacing = min(1.0, missing_sp / n_words * 8)

    # signal 5: words that repeat back to back────────
    repeated   = len(re.findall(r"\b(\w+)\s+\1\b", txt.lower()))
    s5_repeat  = min(1.0, repeated / n_words * 20)

    # signal 6: unevenness in sentence lengths────────
    # high variation means choppy or run-on sentences
    sents_for_len = _SENT_SPLIT.split(txt_no_url)
    sent_lens = [len(s.split()) for s in sents_for_len if len(s.split()) >= 1]
    if len(sent_lens) >= 2:
        import statistics
        mean_l = statistics.mean(sent_lens)
        std_l  = statistics.stdev(sent_lens)
        cv     = std_l / mean_l if mean_l > 0 else 0.0
        # Very short mean (<4 words) is also a fragment signal
        short_penalty = max(0.0, 1.0 - mean_l / 4.0) if mean_l < 4 else 0.0
        s6_sent_len = min(1.0, cv * 0.4 + short_penalty * 0.6)
    else:
        s6_sent_len = 0.0

    # signal 7: ng/nang confusion in Filipino text────────
    if fil_ratio > 0.05:   # only bother if text has Filipino content
        ng_nang_hits = len(_NG_NANG_PAT.findall(txt))
        s7_ng_nang   = min(1.0, ng_nang_hits / n_words * 20)
    else:
        s7_ng_nang = 0.0

    # signal 8: vague or unverifiable attribution words────────
    # words like daw, raw, allegedly without naming an actual source
    vague_hits = len(_VAGUE_ATTR.findall(txt))
    s8_vague   = min(1.0, vague_hits / n_words * 10)

    # combine all signals into the final GQ score────────
    if lt_score is not None:
        # LanguageTool is the main signal for English
        GQ = (0.45 * lt_score         +
              0.10 * s1_repeat_punct  +
              0.10 * s2_caps          +
              0.10 * s3_caps_start    +
              0.05 * s4_spacing       +
              0.05 * s5_repeat        +
              0.05 * s6_sent_len      +
              0.05 * s7_ng_nang       +
              0.05 * s8_vague)
    else:
        # heuristics only for Filipino and Taglish
        GQ = (0.18 * s1_repeat_punct  +
              0.15 * s2_caps          +
              0.12 * s3_caps_start    +
              0.12 * s4_spacing       +
              0.12 * s5_repeat        +
              0.11 * s6_sent_len      +
              0.10 * s7_ng_nang       +
              0.10 * s8_vague)

    return float(min(1.0, GQ))


# Citation Strength (CS): 0 means well-cited and credible, 1 means unsupported.
# Checks for trusted URLs, citation keywords, known organizations, and factual words.
def get_citation_strength(text):
    txt_lower = (text or "").lower()
    txt_orig  = (text or "")
    lang      = safe_detect_lang(text) or "und"

    trusted_domains = [
        "gov.ph", "edu.ph", "mil.ph",
        "rappler.com", "inquirer.net", "abs-cbn.com", "gmanews.tv",
        "philstar.com", "cnnphilippines.com", "manilabulletin.com.ph",
        "news5.com.ph", "sunstar.com.ph", "mindanews.com",
        "interaksyon.com", "malaya.com.ph",
        "bbc.com", "bbc.co.uk", "reuters.com", "nytimes.com",
        "apnews.com", "theguardian.com", "aljazeera.com",
        "bloomberg.com", "washingtonpost.com",
        "who.int", "un.org", "unicef.org", "cdc.gov",
        "nih.gov", "nature.com", "sciencemag.org", "pubmed.ncbi.nlm.nih.gov",
        "verafiles.org", "tsek.ph", "factcheckers.ph", "factrakers.upd.edu.ph",
    ]
    domain_hits = re.findall(
        r'(?:https?://|www\.)([a-zA-Z0-9.\-]+\.[a-z]{2,})', txt_orig
    )
    if domain_hits:
        trusted_hits   = sum(1 for d in domain_hits
                             if any(td in d.lower() for td in trusted_domains))
        untrusted_hits = len(domain_hits) - trusted_hits
        url_score = max(0.0,
                        min(1.0, trusted_hits * 0.50) -
                        min(0.20, untrusted_hits * 0.10))
    else:
        url_score = 0.0

    citation_keywords = [
        "according to", "reported by", "as reported", "stated by",
        "said", "cited", "quoted by", "via", "source:",
        "ayon sa", "iniulat", "batay sa", "sabi ng", "pahayag ng",
        "sinabi ni", "nabanggit", "ayon kay", "base sa",
    ]
    direct_kw_hits = sum(
        1 for kw in citation_keywords
        if re.search(r"(?<!\w)" + re.escape(kw) + r"(?!\w)", txt_lower)
    )

    research_patterns = [
        "researchers found", "researchers verified", "researchers examined",
        "researchers discovered", "researchers reported", "researchers showed",
        "study found", "study published", "study shows", "study showed",
        "study examined", "study confirmed", "study revealed", "study suggests",
        "analysis found", "analysis shows", "analysis reveals", "analysis confirmed",
        "data shows", "data indicates", "data confirms",
        "findings show", "findings indicate", "findings suggest", "findings reveal",
        "results show", "results indicate", "results confirm",
        "experts say", "officials say", "scientists found", "doctors say",
        "peer-reviewed", "peer reviewed", "independently verified",
        "press release", "press statement", "official statement",
        "pag-aaral ay", "natuklasan ng mga mananaliksik",
        "pahayag ng opisyal", "opisyal na ulat",
    ]
    research_hits = sum(1 for p in research_patterns if p in txt_lower)
    kw_score      = min(1.0, (direct_kw_hits * 2 + research_hits) / 4.0)

    ents = []
    try:
        doc_en = nlp_en(txt_orig[:2000])
        ents.extend([e.text for e in doc_en.ents if e.label_ in ("ORG","GPE","PERSON")])
    except Exception:
        pass
    try:
        doc_xx = nlp_xx(txt_orig[:2000])
        ents.extend([e.text for e in doc_xx.ents if e.label_ in ("ORG","GPE","PERSON")])
    except Exception:
        pass

    known_orgs = {
        "doh","dfa","pnp","nbi","dilg","deped","ched","afp","comelec",
        "pagasa","phivolcs","denr","dti","dof","dpwh","dost","dole","dbm",
        "dswd","pdea","mmda","senate","malacañang","malacanang",
        "office of the president","supreme court",
        "who","united nations","unicef","unesco","wto","cdc","imf",
        "world bank","fda",
        "abs-cbn","gma","rappler","inquirer","philstar","sunstar",
        "manila bulletin","philippine star","verafiles","tsek",
        "factrakers","factcheckers","news5",
        "cnn","bbc","reuters","associated press","new york times",
        "washington post","guardian","aljazeera","bloomberg",
    }
    org_hits_dict = sum(
        1 for o in known_orgs
        if re.search(r"\b" + re.escape(o) + r"\b", txt_lower)
    )
    acronyms  = re.findall(r"\b[A-Z]{2,}\b", txt_orig)
    acr_hits  = sum(1 for a in acronyms if a.lower() in known_orgs)
    ner_count = len({e.lower() for e in ents if len(e) > 2})
    org_score = min(1.0, (ner_count + org_hits_dict + acr_hits) / 4.0)

    english_fw = [
        "data","report","study","confirmed","survey","analysis","official",
        "evidence","research","investigation","results","statistics",
        "findings","published","documented","reviewed","verified","validated",
        "assessment","evaluation","experiment","peer-reviewed","recorded",
        "demonstrated","observed","press conference","press release",
    ]
    tagalog_fw = [
        "ulat","pag-aaral","imbestigasyon","datos","katibayan","resulta",
        "eksperimento","pagsusuri","pagmamasid","sinuri","pinatunayan",
        "narekord","nasuri","pagsukat","opisyal","pahayag",
    ]
    fact_list  = english_fw + tagalog_fw   # always include both
    fact_hits  = sum(1 for w in fact_list
                     if re.search(r"\b" + re.escape(w) + r"\b", txt_lower))
    fact_score = min(1.0, fact_hits / 3.0)

    credibility = (0.25 * url_score  +
                   0.30 * org_score  +
                   0.25 * kw_score   +
                   0.20 * fact_score)

    if url_score > 0.30 and org_score > 0.30 and kw_score > 0.30:
        credibility = min(1.0, credibility + 0.10)
    if research_hits >= 2 and fact_score >= 0.60:
        credibility = min(1.0, credibility + 0.15)

    return round(1.0 - min(1.0, credibility), 4)


# =============================================================================
# SMOKE TEST — shows hybrid path for each example
# =============================================================================
def _et_debug(text):
    """Show hybrid decomposition for a single text."""
    tokens = re.findall(r"\w+", text.lower())
    vc = _vader_coverage(tokens) if VADER_OK else 0
    fr = _filipino_token_ratio(tokens)
    comp = _vader.polarity_scores(text)["compound"] if VADER_OK else 0
    pos  = sum(1 for w in tokens if w in filipino_positive)
    neg  = sum(1 for w in tokens if w in filipino_negative)
    et   = get_emotional_tone(text)
    gq   = get_grammar_quality(text)
    cs   = get_citation_strength(text)
    return (f"  vader_cov={vc:.2f} fil_ratio={fr:.2f} "
            f"vader_comp={comp:+.3f} lex_pos={pos} lex_neg={neg} "
            f"→ ET={et:.3f} GQ={gq:.3f} CS={cs:.3f}")

_tests = [
    ("BREAKING!!! Marcos GONE!!! The government is HIDING the truth!!!",
     "English clickbait"),
    ("According to the Department of Health (DOH), the latest survey "
     "confirmed vaccination rates have risen. https://doh.gov.ph",
     "Well-cited credible article"),
    ("Trump is going to wage war with China",
     "Grammatical English statement"),
    ("Trump going wage war with China",
     "Ungrammatical English (missing aux+prep)"),
    ("Grabe naman!!! PANGGULO ito ng gobyerno. Wala silang pakialam!",
     "Pure Tagalog emotional"),
    ("Grabe! The government is HIDING the truth pala! Sobrang unfair naman!",
     "Taglish code-switch"),
    ("Ayon sa DOH, tumaas ang bilang ng mga bakunado ngayong taon.",
     "Tagalog cited statement"),
]

for txt, desc in _tests:
    detail = _et_debug(txt)
    print(f"  {desc:<40}{detail}")



# Cell 7:  Image loader for tsek ph and functions for Image features

import os, re, hashlib, time, base64
from pathlib import Path
import numpy as np

try:
    import cv2
    CV2_OK = True
except Exception as e:
    cv2 = None
    CV2_OK = False
    print("OpenCV not available:", e)

try:
    import requests
    REQUESTS_OK = True
except Exception:
    import urllib.request as _urllib
    REQUESTS_OK = False

IMAGE_CACHE_DIR = Path("/kaggle/working/image_cache")
IMAGE_CACHE_DIR.mkdir(parents=True, exist_ok=True)

# helpers
def is_url(x):
    return isinstance(x, str) and x.lower().startswith(("http://", "https://", "data:"))

def url_cache_path(url):
    h = hashlib.sha1(url.encode("utf-8")).hexdigest()
    m = re.search(r"\.(jpg|jpeg|png|gif|bmp|webp)(?:[\?#]|$)", url, flags=re.I)
    ext = "." + m.group(1).lower() if m else ".jpg"
    return IMAGE_CACHE_DIR / f"{h}{ext}"

# downloader
def download_image_bytes(url, timeout=8, max_retries=3):
    cache_p = url_cache_path(url)
    if cache_p.exists() and cache_p.stat().st_size > 0:
        try:
            return cache_p.read_bytes()
        except Exception:
            pass

    if url.startswith("data:"):
        try:
            header, b64 = url.split(",", 1)
            return base64.b64decode(b64)
        except Exception as e:
            raise RuntimeError("Failed to decode data URI: " + str(e))

    headers = {
        "User-Agent": (
            "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
            "AppleWebKit/537.36 (KHTML, like Gecko) "
            "Chrome/126.0.0.0 Safari/537.36"
        ),
        "Accept": "image/avif,image/webp,image/apng,image/*,*/*;q=0.8",
        "Referer": "https://www.tsek.ph/",
        "Accept-Language": "en-US,en;q=0.9",
    }

    last_err = None
    for attempt in range(max_retries):
        try:
            if REQUESTS_OK:
                resp = requests.get(
                    url, timeout=timeout, headers=headers,
                    allow_redirects=True, stream=True, verify=False
                )

                if resp.status_code == 404 and "i0.wp.com/www.tsek.ph/" in url:
                    alt_url = url.replace("https://i0.wp.com/www.tsek.ph/", "https://www.tsek.ph/")
                    print(f"[retry] 404 on CDN, trying origin: {alt_url}")
                    resp = requests.get(
                        alt_url, timeout=timeout, headers=headers,
                        allow_redirects=True, stream=True, verify=False
                    )

                resp.raise_for_status()
                content = resp.content
            else:
                with _urllib.urlopen(url, timeout=timeout) as fh:
                    content = fh.read()

            try:
                cache_p.write_bytes(content)
            except Exception:
                pass

            print(f"[ok] {url}")
            return content

        except Exception as e:
            last_err = e
            print(f"[warn] attempt {attempt+1} for {url}: {e}")
            time.sleep(0.5 * (attempt + 1))

    raise RuntimeError(f"Failed to download {url}: {last_err}")


# Image loader 
def load_image_flexible(path_or_img):
    if isinstance(path_or_img, np.ndarray):
        return path_or_img
    if path_or_img is None:
        return None
    s = str(path_or_img).strip()
    if is_url(s):
        try:
            img_bytes = download_image_bytes(s)
            if img_bytes is None:
                return None
            arr = np.frombuffer(img_bytes, dtype=np.uint8)
            img = cv2.imdecode(arr, cv2.IMREAD_COLOR) if CV2_OK else None
            if img is None and CV2_OK:
                tmp = url_cache_path(s)
                tmp.write_bytes(img_bytes)
                img = cv2.imread(str(tmp))
            return img
        except Exception as e:
            print(f"[image fetch failed] {s} -> {e}")
            return None
    else:
        p = Path(s)
        if p.exists():
            try:
                return cv2.imread(str(p)) if CV2_OK else None
            except Exception:
                return None
        return None

# Image Emotional Provactiveness (IEP)
def get_image_iepp(img_or_path):
    """Image Emotional Provocativeness Proxy [0,1]."""
    try:
        img = load_image_flexible(img_or_path) if isinstance(img_or_path, (str, Path, np.ndarray)) else None
        if img is None:
            return 0.4  # fallback if no image
        hsv = cv2.cvtColor(img, cv2.COLOR_BGR2HSV).astype(np.float32)
        s = float(np.mean(hsv[:, :, 1]) / 255.0)           # saturation
        v = float(np.mean(hsv[:, :, 2]) / 255.0)           # brightness
        contrast = float(np.std(hsv[:, :, 2]) / 128.0)     # brightness contrast

        # Sharpness / activity
        gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
        sharpness = float(cv2.Laplacian(gray, cv2.CV_64F).var() / 1000.0)
        sharpness = min(1.0, max(0.0, sharpness))

        # Weighted combination
        score = 0.5 * s + 0.25 * (1.0 - v) + 0.15 * contrast + 0.10 * sharpness
        return float(min(1.0, max(0.0, score)))
    except Exception as ex:
        print("get_image_iepp error:", ex)
        return 0.4

# Picture Text Consistency (PTC)       
# Stop words filtered from PTC comparison to avoid false matches
_PTC_STOP = {
    "the","a","an","is","in","of","to","and","or","for","at","on","by",
    "it","its","was","are","be","has","had","have","this","that","with",
    "from","but","not","they","he","she","we","you","do","did","will",
    "can","may","his","her","our","their","been","all","one","two",
    "jpg","jpeg","png","gif","webp","bmp","svg","img","image","photo",
    "pic","picture","file","upload","uploaded",
}

def get_image_ptc(text, img_or_path):
    """
    Picture-Text Consistency  [0, 1]
    0 = consistent (image description matches article text)
    1 = inconsistent (no meaningful overlap)

    img_or_path may be:
      - A URL/file path (str starting with http/https//) → filename extracted
      - A plain-text description (str, e.g. alt-text + caption)  → used directly
      - A numpy array  → returns 0.5 (no text to compare)
    """
    try:
        from urllib.parse import urlparse, unquote
        from pathlib import Path

        if isinstance(img_or_path, str):
            s = img_or_path.strip()
            # Detect whether this is a URL/path or a plain-text description
            is_url  = s.startswith(("http://","https://","data://","//"))
            is_path = (not is_url) and (
                "/" in s or "\\" in s or
                any(s.lower().endswith(ext)
                    for ext in (".jpg",".jpeg",".png",".gif",".webp",".bmp"))
            )
            if is_url or is_path:
                p        = urlparse(s).path
                img_text = unquote(Path(p).name.lower())
                src_type = "filename"
            else:
                # Plain text — alt-text or caption provided directly
                img_text = s.lower()
                src_type = "alt-text/caption"
        else:
            return 0.5   # numpy array — no text available

        # Tokenise and filter stop words + very short tokens
        article_words = {w for w in re.findall(r"[a-z]+", (text or "").lower())
                         if len(w) > 2 and w not in _PTC_STOP}
        img_words     = {w for w in re.findall(r"[a-z]+", img_text)
                         if len(w) > 2 and w not in _PTC_STOP}

        if not article_words or not img_words:
            return 0.5   # insufficient tokens

        overlap = len(article_words & img_words)
        sim     = overlap / max(1, len(img_words))
        return float(max(0.0, min(1.0, 1.0 - sim)))

    except Exception as ex:
        print("get_image_ptc error:", ex)
        return 0.5


# Image column detector 
def detect_image_column(df, sample_rows=200):
    url_re = re.compile(r"https?://", flags=re.I)
    img_ext_re = re.compile(r"\.(jpg|jpeg|png|gif|bmp|webp)(?:[\?#]|$)", flags=re.I)
    candidates = []
    for col in df.columns:
        if df[col].dtype == object:
            vals = df[col].dropna().astype(str).str.strip()
            if len(vals) == 0:
                continue
            sample = vals.head(sample_rows)
            pct_url = sample.str.contains(url_re).mean()
            pct_ext = sample.str.contains(img_ext_re).mean()
            score = pct_url * 0.7 + pct_ext * 0.3
            candidates.append((score, col, pct_url, pct_ext))
    candidates.sort(reverse=True, key=lambda x: x[0])
    if candidates and candidates[0][0] >= 0.10:
        best = candidates[0]
        print(f"Auto-detected image column: {best[1]} (url_frac={best[2]:.2f}, ext_frac={best[3]:.2f})")
        return best[1]
    print("No image-like column auto-detected.")
    return None

