# Defines triangular membership functions for low, medium, and high.
# The low MF uses a left plateau so a value of 0 returns 1.0 instead of 0.
# The high MF uses a right plateau so a value of 1.0 also returns 1.0.
# The medium band is wider than usual to create smooth overlaps between levels.



def triangle_mf(x, a, b, c):
    """Compute triangular membership. Handles plateau shapes at the boundaries."""
    try:
        x = float(x)
    except Exception:
        return 0.0
    # left plateau shape: full membership for all values up to b
    if a == b:
        if x <= b: return 1.0
        if x >= c: return 0.0
        return (c - x) / (c - b)
    # right plateau shape: full membership for all values from b upward
    if b == c:
        if x >= b: return 1.0
        if x <= a: return 0.0
        return (x - a) / (b - a)
    # standard triangle shape
    if x <= a or x >= c:
        return 0.0
    if a < x <= b:
        return (x - a) / (b - a)
    if b < x < c:
        return (c - x) / (c - b)
    return 0.0


MF_PARAMS = {
    "low":    (0.0, 0.0, 0.5),
    "medium": (0.2, 0.5, 0.8),
    "high":   (0.5, 1.0, 1.0),
}


def fuzzify_feature(x):
    return {k: triangle_mf(x, *p) for k, p in MF_PARAMS.items()}


# Boundary sanity checks


# Each rule maps a combination of feature levels to a credibility output z.
# Higher z means more credible. Rules are grouped from most credible to most suspicious.
# Image feature rules only fire when an image is included in the analysis.


RULES = [
    # rules where all signals point strongly toward credibility
    ([("CS","low"), ("GQ","low"), ("ET","low")], 0.95),
    ([("CS","low"), ("GQ","low")],               0.93),
    ([("CS","low"), ("ET","low")],               0.92),
    ([("GQ","low"), ("ET","low")],               0.72),
    ([("CS","low")],                             0.90),
    ([("GQ","low")],                             0.65),
    ([("ET","low")],                             0.60),

    # rules where most signals suggest the article is credible
    ([("CS","medium"), ("GQ","low"), ("ET","low")],       0.80),
    ([("CS","low"),    ("GQ","medium"), ("ET","low")],    0.82),
    ([("CS","low"),    ("GQ","low"), ("ET","medium")],    0.80),
    ([("CS","medium"), ("GQ","medium"), ("ET","low")],    0.75),
    ([("CS","medium"), ("GQ","low"), ("ET","medium")],    0.72),
    ([("CS","low"),    ("GQ","medium"), ("ET","medium")], 0.74),
    ([("CS","medium"), ("GQ","medium")],                  0.68),
    ([("CS","medium"), ("ET","medium")],                  0.67),
    ([("GQ","medium"), ("ET","medium")],                  0.65),

    # rules where signals are mixed or conflicting
    ([("CS","medium"), ("GQ","medium"), ("ET","medium")], 0.55),
    ([("CS","low"),    ("GQ","high")],                    0.55),
    ([("CS","high"),   ("GQ","low")],                     0.42),
    ([("CS","medium"), ("ET","high")],                    0.32),
    ([("GQ","medium"), ("ET","high")],                    0.35),
    ([("CS","high"),   ("ET","medium")],                  0.40),

    # rules where signals lean toward the article being fake
    ([("CS","high"),   ("GQ","medium")],                  0.35),
    ([("CS","medium"), ("GQ","high")],                    0.35),
    ([("ET","medium"), ("GQ","high")],                    0.33),
    ([("ET","high"),   ("CS","high")],                    0.12),
    ([("CS","high"),   ("GQ","high")],                    0.22),

    # rules where signals strongly suggest the article is fake
    ([("ET","high"),  ("PTC","high")],                    0.12),
    ([("IEP","high"), ("PTC","high")],                    0.10),
    ([("CS","high"),  ("GQ","high"), ("ET","high")],      0.05),
    ([("GQ","high"),  ("ET","high")],                     0.15),

    # rules that use image features, only active when an image is provided
    ([("PTC","high"), ("CS","medium")],                   0.18),
    ([("IEP","high"), ("CS","high")],                     0.15),

    # calm and well-written articles with no citations are often fabricated
    ([("CS","high"), ("GQ","low"), ("ET","low")],         0.28),
    ([("CS","high"), ("ET","low")],                       0.35),

    # fallback rules that fire on a single feature when no combination applies
    ([("CS","medium")],  0.52),
    ([("GQ","medium")],  0.48),
    ([("ET","medium")],  0.45),
    ([("CS","high")],    0.25),
    ([("GQ","high")],    0.35),
    ([("ET","high")],    0.30),
]




def evaluate_rules_and_sugeno(fuzzified_dict, rules=RULES):
    num = 0.0
    den = 0.0
    details = []
    for ants, z in rules:
        # firing weight is the minimum membership across all antecedents
        w = 1.0
        for f, lab in ants:
            w = min(w, fuzzified_dict.get(f, {}).get(lab, 0.0))
        num += w * z
        den += w
        details.append({"ants": ants, "z": z, "w": float(w)})
    F = float(num/den) if den > 0 else 0.5
    return F, details


# Runs the full pipeline on one article: feature extraction, fuzzification,
# rule evaluation, and Sugeno defuzzification to get a credibility score and label.


import re

# detect the language of the text using langdetect
def safe_detect_lang(text):
    try:
        return detect(text or "")
    except Exception:
        return "und"


DEFAULT_THRESHOLDS = [0.20, 0.35, 0.50, 0.65, 0.80]
BINARY_THRESHOLD   = 0.5


def cs_to_label(cs, thresholds=DEFAULT_THRESHOLDS):
    if cs is None:
        return "error"
    b1, b2, b3, b4, b5 = thresholds
    if cs >= b5: return "Real"
    if cs >= b4: return "Mostly Real"
    if cs >= b3: return "Half Real"
    if cs >= b2: return "Mostly Fake"
    if cs >= b1: return "Fake"
    return "Pants on Fire"


def cs_to_binary_label(cs):
    if cs is None:
        return "error"
    return "True" if cs >= BINARY_THRESHOLD else "False"


def evaluate_article(article_text, image_path=None, use_images=False,
                     extract_claim=False):
    """
    Parameters
    ----------
    article_text  : str   raw text to classify
    image_path    : str/bytes/array  optional image
    use_images    : bool  turn on multimodal rules
    extract_claim : bool  if True and the text looks like a fact-check
                          article, run `extract_claim_from_factcheck` first
    """
    text = clean_html(article_text) if article_text else ""

    if extract_claim:
        try:
            text = extract_claim_from_factcheck(text)
        except Exception:
            pass

    lang = safe_detect_lang(text)

    # compute raw feature scores from the text
    raw = {
        "ET": get_emotional_tone(text, lang),
        "GQ": get_grammar_quality(text, lang),
        "CS": get_citation_strength(text),
    }

    if use_images and image_path is not None:
        try:
            raw["IEP"] = get_image_iepp(image_path)
            raw["PTC"] = get_image_ptc(text, image_path)
        except Exception:
            raw["IEP"] = 0.0
            raw["PTC"] = 0.0

    # convert raw scores to fuzzy membership degrees
    fuzzified = {k: fuzzify_feature(v) for k, v in raw.items()}

    # select only text rules or all rules depending on whether images are used
    if use_images:
        active_rules = RULES
    else:
        active_rules = [(ants, z) for ants, z in RULES
                        if all(f not in ("IEP", "PTC") for f, _ in ants)]

    # run Sugeno inference to get the credibility score
    try:
        F, details = evaluate_rules_and_sugeno(fuzzified, rules=active_rules)
    except Exception as e:
        print("Sugeno error:", e)
        F, details = 0.5, []

    if F is None:
        F = 0.5

    return {
        "raw":           raw,
        "fuzzified":     fuzzified,
        "CS":            F,
        "multi_label":   cs_to_label(F),
        "binary_label":  cs_to_binary_label(F),
        "details":       details,
        "lang":          lang,
    }


