# generate_explanation is defined here (Cell 12) so it is available
# to Cell 13 (batch) AND Cell 15/16 (demos). Defined ONCE, used everywhere.
# ─────────────────────────────────────────────────────────────────────
# Explanation generator for the Sugeno classification result
def generate_explanation(raw, fuzzified, F, multi_label, use_images=False):
    """Generate a plain-language explanation for the classification result."""

    ET  = raw.get("ET", 0.5)
    GQ  = raw.get("GQ", 0.5)
    CS  = raw.get("CS", 0.5)
    IEP = raw.get("IEP")
    PTC = raw.get("PTC")

    # ── Linguistic interpretation ─────────────────────────────────────────
    def et_desc(v):
        if v < 0.15: return "very calm and neutral"
        if v < 0.30: return "mostly neutral"
        if v < 0.50: return "moderately emotional"
        if v < 0.70: return "notably emotional or charged"
        return "highly emotional and provocative"

    def gq_desc(v):
        if v < 0.10: return "professionally written, no quality issues detected"
        if v < 0.25: return "mostly well-written"
        if v < 0.50: return "showing some writing irregularities"
        if v < 0.70: return "exhibiting notable quality issues"
        return "exhibiting significant writing problems"

    def cs_desc(v):
        if v < 0.20: return "well-supported with citations and credible sources"
        if v < 0.40: return "reasonably cited with some credible indicators"
        if v < 0.60: return "partially supported but lacking strong citations"
        if v < 0.80: return "lacking clear citations or source attribution"
        return "unsupported — no credible sources detected"

    def iep_desc(v):
        if v > 0.60: return "visually provocative"
        if v > 0.35: return "moderately provocative"
        return "visually neutral"

    def ptc_desc(v):
        if v > 0.60: return "inconsistent with"
        if v > 0.35: return "partially consistent with"
        return "consistent with"

    def dom_mf(key):
        fd = fuzzified.get(key, {})
        if not fd: return "medium"
        return max(fd.items(), key=lambda x: x[1])[0]

    # check which rules fired to know if images actually influenced the result
    active_all  = RULES
    active_text = [(a,z) for a,z in RULES
                   if all(f not in ("IEP","PTC") for f,_ in a)]
    active_img  = [(a,z) for a,z in RULES
                   if any(f in ("IEP","PTC") for f,_ in a)]
    active_used = RULES if use_images else active_text

    def compute_fired(rule_list):
        records = []
        for ants, z in rule_list:
            w = 1.0
            for f, lab in ants:
                w = min(w, fuzzified.get(f, {}).get(lab, 0.0))
            if w > 0.001:
                records.append((ants, z, w, w * z))
        return records

    fired_used = compute_fired(active_used)
    fired_used.sort(key=lambda x: -x[3])

    # check if image rules actually had any effect on the score
    img_rules_fired = compute_fired(active_img) if use_images else []
    images_influenced = bool(img_rules_fired)

    # ── Per-feature weighted contribution ─────────────────────────────────
    feature_num  = {k: 0.0 for k in raw}
    total_num, total_den = 0.0, 0.0
    for ants, z, w, wz in fired_used:
        total_num += wz
        total_den += w
        for f, _ in ants:
            if f in feature_num:
                feature_num[f] += wz

    dominant_feat = max(feature_num, key=feature_num.get) if feature_num else "CS"
    dominant_pct  = (feature_num[dominant_feat] / total_num * 100) if total_num > 0 else 0.0

    # ── Credibility direction — ONLY include image features if they fired ─
    # FIX: IEP direction threshold tightened from 0.50 to 0.35.
    #      "Moderately provocative" (IEP > 0.35) is a suspicion signal,
    #      not a credibility signal.
    def et_dir(v):  return -1 if v > 0.45 else 1
    def gq_dir(v):  return -1 if v > 0.45 else 1
    def cs_dir(v):  return -1 if v > 0.55 else 1   # CS is a suspicion score
    def iep_dir(v): return -1 if v > 0.35 else 1   # tightened from 0.50
    def ptc_dir(v): return -1 if v > 0.50 else 1

    directions = {"ET": et_dir(ET), "GQ": gq_dir(GQ), "CS": cs_dir(CS)}
    # Only include image features in conflict if they actually fired rules
    if use_images and images_influenced:
        if IEP is not None: directions["IEP"] = iep_dir(IEP)
        if PTC is not None: directions["PTC"] = ptc_dir(PTC)

    credible_feats   = [k for k,d in directions.items() if d ==  1]
    suspicious_feats = [k for k,d in directions.items() if d == -1]
    has_conflict     = bool(credible_feats and suspicious_feats)

    # ── Boundary proximity ────────────────────────────────────────────────
    thresholds = [
        (0.80, "Real",        "Mostly Real"),
        (0.65, "Mostly Real", "Half Real"),
        (0.50, "Half Real",   "Mostly Fake"),
        (0.35, "Mostly Fake", "Fake"),
        (0.20, "Fake",        "Pants on Fire"),
    ]
    proximity_note = ""
    for thresh, upper, lower in thresholds:
        if abs(F - thresh) < 0.05:
            dist = abs(F - thresh)
            side = "above" if F >= thresh else "below"
            adj  = upper if F >= thresh else lower
            alt  = lower if F >= thresh else upper
            proximity_note = (
                f"<span style='color:#f0c040;'>⚠ Boundary proximity:</span> "
                f"The score {F:.4f} is only {dist:.4f} {side} the "
                f"<b>{adj}</b> / <b>{alt}</b> threshold ({thresh:.2f}). "
                f"A small shift in any feature could change the classification — "
                f"a property of continuous T-S fuzzy output, unlike a crisp classifier."
            )
            break

    # ── Build explanation ─────────────────────────────────────────────────
    lines = []

    # sentence 1: describe what the feature scores mean in plain language
    lines.append(
        f"The article's language was found to be <b>{et_desc(ET)}</b> "
        f"(ET&nbsp;=&nbsp;{ET:.3f}), "
        f"<b>{gq_desc(GQ)}</b> (GQ&nbsp;=&nbsp;{GQ:.3f}), "
        f"and <b>{cs_desc(CS)}</b> (CS&nbsp;=&nbsp;{CS:.3f})."
    )

    # 2. Image feature summary (if computed)
    if use_images and IEP is not None and PTC is not None:
        influence_note = (
            "" if images_influenced
            else " <i style='color:#888;'>(computed but did not influence "
                 "the final score — image rules require higher IEP or PTC "
                 "membership levels to fire)</i>"
        )
        lines.append(
            f"The headline image was <b>{iep_desc(IEP)}</b> "
            f"(IEP&nbsp;=&nbsp;{IEP:.3f}) and "
            f"<b>{ptc_desc(PTC)} the article text</b> "
            f"(PTC&nbsp;=&nbsp;{PTC:.3f}).{influence_note}"
        )

    # sentence 3: show which fuzzy level each feature mapped to
    mf_parts = [f"<b>{k}</b>&nbsp;→&nbsp;<b>{dom_mf(k)}</b>" for k in raw]
    lines.append(
        "After fuzzification using triangular membership functions "
        "(low, medium, high), each feature mapped to: "
        + ", ".join(mf_parts) + "."
    )

    # sentence 4: note if features conflict and explain how the FIS handles it
    scope_note = (
        "" if images_influenced
        else " (text features only — image rules did not fire)"
    )
    if has_conflict:
        cred_str = ", ".join(f"<b>{k}</b>" for k in credible_feats)
        susp_str = ", ".join(f"<b>{k}</b>" for k in suspicious_feats)
        lines.append(
            f"<span style='color:#f0c040;'>⚠ Conflicting signals detected"
            f"{scope_note}:</span> "
            f"{cred_str} pointed toward credibility, while {susp_str} "
            f"indicated suspicion. Rather than choosing one side, the T-S FIS "
            f"fired rules from both directions simultaneously with partial "
            f"membership weights, balancing the competing evidence in the "
            f"weighted average output."
        )
    else:
        dir_word = "credibility" if F >= 0.50 else "suspicion"
        lines.append(
            f"All features{scope_note} pointed consistently toward "
            f"<b>{dir_word}</b> with no conflicting signals."
        )

    # sentence 5: identify which feature had the most influence
    lines.append(
        f"Across all <b>{len(fired_used)} rules</b> that fired, "
        f"<b>{dominant_feat}</b> was the most influential feature, "
        f"accounting for approximately <b>{dominant_pct:.1f}%</b> of the "
        f"total weighted credibility sum — it had the greatest influence on "
        f"which rules fired with the highest weights."
    )

    # sentence 6: list the three rules that contributed most to the result
    top3 = fired_used[:3]
    rule_strs = []
    for i, (ants, z, w, wz) in enumerate(top3):
        ant_str = " ∧ ".join(
            f"<b>{f}</b>&nbsp;is&nbsp;<b>{lab}</b>" for f, lab in ants
        )
        rule_strs.append(
            f"Rule {i+1}: IF {ant_str} → "
            f"z&nbsp;=&nbsp;{z:.2f} "
            f"(w&nbsp;=&nbsp;{w:.3f}, "
            f"w·z&nbsp;=&nbsp;{wz:.4f})"
        )
    lines.append(
        "The three rules contributing most to the Sugeno weighted average:<br>"
        + "<br>".join(rule_strs)
    )

    # sentence 7: add a note if the score is near a classification boundary
    if proximity_note:
        lines.append(proximity_note)

    # sentence 8: state the final formula and classification with a brief rationale
    if F >= 0.80:
        reason = ("strongly aligns with credibility indicators — low emotional "
                  "tone, clean writing, and well-cited content drove "
                  "high-z credibility rules to dominate")
    elif F >= 0.65:
        reason = ("aligns more with credibility indicators; credibility rules "
                  "outweighed suspicion rules in the weighted sum")
    elif F >= 0.50:
        reason = ("falls in the mixed zone — credibility and suspicion rules "
                  "fired with comparable weights")
    elif F >= 0.35:
        reason = ("shows more fake news indicators — rules associated with "
                  "high emotional tone or missing citations contributed more "
                  "weight to the low-z end of the spectrum")
    elif F >= 0.20:
        reason = ("lacks credibility indicators — high-z credibility rules "
                  "fired weakly while low-z suspicious rules dominated")
    else:
        reason = ("exhibits strong fake news characteristics — nearly all "
                  "weight accumulated in low-z rules")

    lines.append(
        f"The Type&nbsp;1 Takagi-Sugeno zero-order FIS computed a final "
        f"credibility score of <b>{F:.4f}</b> via weighted average: "
        f"F&nbsp;=&nbsp;Σ(wᵢ·zᵢ)&nbsp;/&nbsp;Σwᵢ&nbsp;=&nbsp;"
        f"{total_num:.4f}&nbsp;/&nbsp;{total_den:.4f}&nbsp;=&nbsp;{F:.4f}. "
        f"This {reason}, resulting in a classification of "
        f"<b>&ldquo;{multi_label}&rdquo;</b>."
    )

    return "<br><br>".join(lines)


